require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;use MongoDB\BSON\UTCDateTime;
setJsonResponse();handleCors();logRequest();requireCustomer();if($_SERVER['REQUEST_METHOD']!=='POST')sendResponse(false,'Method not allowed.',null,405);$d=json_decode(file_get_contents('php://input'),true);$vehicleId=trim($d['vehicleId']??'');$st=trim($d['startDate']??'');$et=trim($d['endDate']??'');$pickup=trim($d['pickupLocation']??'');$return=trim($d['returnLocation']??'');if(!preg_match('/^[a-f0-9]{24}$/i',$vehicleId)||$pickup===''||$return==='')sendResponse(false,'Vehicle, pickup location and return location are required.',null,400);$start=DateTimeImmutable::createFromFormat('!Y-m-d',$st);$end=DateTimeImmutable::createFromFormat('!Y-m-d',$et);$today=new DateTimeImmutable('today');if(!$start||!$end||$start<$today||$end<$start)sendResponse(false,'Please choose valid rental dates.',null,400);
try{$db=getDatabase();$vid=new ObjectId($vehicleId);$v=$db->vehicles->findOne(['_id'=>$vid]);if(!$v)sendResponse(false,'Vehicle not found.',null,404);if(($v['status']??'Available')==='Maintenance')sendResponse(false,'Vehicle is currently under maintenance.',null,409);$su=new UTCDateTime($start->getTimestamp()*1000);$eu=new UTCDateTime($end->getTimestamp()*1000);$blocked=$db->bookings->findOne(['vehicleId'=>$vid,'status'=>['$in'=>['Approved','Confirmed','Active','Returned']],'startDate'=>['$lte'=>$eu],'endDate'=>['$gte'=>$su]]);if($blocked)sendResponse(false,'These dates are already reserved.',null,409);$days=(int)$start->diff($end)->days+1;$price=(float)($v['pricePerDay']??0);$total=$days*$price;$r=$db->bookings->insertOne(['userId'=>new ObjectId($_SESSION['user_id']),'vehicleId'=>$vid,'vehicleName'=>(string)$v['name'],'vehicleType'=>(string)($v['type']??''),'pricePerDay'=>$price,'startDate'=>$su,'endDate'=>$eu,'pickupLocation'=>$pickup,'returnLocation'=>$return,'totalDays'=>$days,'totalPrice'=>$total,'status'=>'Pending','paymentStatus'=>'Not Paid','createdAt'=>new UTCDateTime(),'updatedAt'=>new UTCDateTime()]);sendResponse(true,'Booking request sent. Waiting for admin approval.',['bookingId'=>(string)$r->getInsertedId()],201);}catch(Throwable $e){error_log('Booking create: '.$e->getMessage());sendResponse(false,'Booking request failed.',null,500);}